import type { UseSignaturePadReturn } from '@ark-ui/vue/signature-pad';
import type { ComputedRef, InjectionKey, UnwrapRef } from 'vue';

export type SignaturePadApi = UnwrapRef<UseSignaturePadReturn> & {
  readOnly: boolean;
};

export const signaturePadReadOnlyKey: InjectionKey<ComputedRef<boolean | undefined>> =
  Symbol('SignaturePadReadOnly');

import { useFieldContext } from '@ark-ui/vue/field';
import { useSignaturePad as useSignaturePadPrimitive } from '@ark-ui/vue/signature-pad';
import type { UseSignaturePadProps } from '@ark-ui/vue/signature-pad';
import { computed, toValue, unref } from 'vue';
import type { ComputedRef, MaybeRef } from 'vue';
import type { SignaturePadApi } from './context';

type SignaturePadHookProps = MaybeRef<UseSignaturePadProps> | undefined;

export const useSignaturePad = (
  props?: SignaturePadHookProps,
  emit?: Parameters<typeof useSignaturePadPrimitive>[1],
): ComputedRef<SignaturePadApi> => {
  const field = useFieldContext();
  const signaturePad = useSignaturePadPrimitive(props, emit);
  return computed(() => ({
    ...signaturePad.value,
    readOnly: toValue(props)?.readOnly ?? unref(field)?.readOnly ?? false,
  }));
};

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: inline-flex;
    flex-direction: column;
    gap: var(--moduix-spacing-2);
    width: var(--moduix-signature-pad-width, 17.5rem);
    max-width: 100%;
    color: var(--moduix-color-foreground);

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;
  }

  .control {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    height: var(--moduix-signature-pad-height, 10rem);
    border: var(--moduix-border-width-sm) solid
      var(--moduix-signature-pad-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-signature-pad-radius, var(--moduix-radius-md));
    background-color: var(--moduix-signature-pad-bg, var(--moduix-color-background));
    box-shadow: var(--moduix-shadow-sm);
    outline: none;
    overflow: hidden;
    transition:
      border-color var(--moduix-transition-default),
      box-shadow var(--moduix-transition-default);

    &[data-disabled] {
      cursor: not-allowed;
    }

    &:focus-visible {
      border-color: var(--moduix-color-ring);
      box-shadow: 0 0 0 var(--moduix-focus-ring-width) var(--moduix-color-ring);
    }
  }

  .segment {
    fill: var(--moduix-signature-pad-stroke-color, currentColor);
  }

  .guide {
    position: absolute;
    inset-inline: var(--moduix-spacing-6);
    bottom: var(--moduix-spacing-8);
    border-bottom: var(--moduix-border-width-sm) dashed
      var(--moduix-signature-pad-guide-color, var(--moduix-color-border));
    pointer-events: none;
  }

  .clearTrigger {
    --moduix-close-button-size: var(--moduix-size-xs);
    /* The disabled root already dims the whole pad. */
    --moduix-close-button-disabled-opacity: 1;

    position: absolute;
    top: var(--moduix-spacing-2);
    inset-inline-end: var(--moduix-spacing-2);
  }
}

import {
